"""Exact-model setting frames generated by each appliance's vendor codec."""

import pytest

from midea_ac_lan.ble.appliances import HEATER, HOOD, setting


@pytest.mark.parametrize(
    ("profile", "key", "value", "wire"),
    [
        (HOOD, "light", True, "aa12b6000000000000021101020201ffffff22"),
        (HOOD, "light", False, "aa12b6000000000000021101020200ffffff23"),
        (
            HEATER,
            "beep",
            True,
            "aa1ee3000000000000021415010000000000000000000000000000000001d2",
        ),
        (
            HEATER,
            "beep",
            False,
            "aa1ee3000000000000021415000000000000000000000000000000000000d4",
        ),
    ],
)
def test_setting(profile, key, value, wire):
    assert setting(profile, key, value) == bytes.fromhex(wire)


@pytest.mark.parametrize("profile", [HOOD, HEATER])
def test_power_is_not_a_ble_setting(profile):
    with pytest.raises(ValueError, match="Unsupported"):
        setting(profile, "power", True)


def test_dishwasher_only_encodes_isolated_settings():
    from midea_ac_lan.ble.appliances import DISH

    assert DISH.query.hex() == "aa0be1000000000000030011"
    for value in (True, False):
        frame = setting(DISH, "beep", value)
        assert frame[9:12] == bytes.fromhex("029005")
        assert frame[16] == int(value)
        assert len(frame) == 49 and sum(frame[1:]) % 256 == 0
        lock = setting(DISH, "child_lock", value)
        assert lock[10:12] == bytes((0x83, 3 if value else 4))
    for key in ("start", "program", "power", "operator", "raw"):
        with pytest.raises(ValueError):
            setting(DISH, key, True)
